head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jlddst10200";

// 화면 진입점 — 초기화 단계를 데이터 의존 순서로 호출한다.

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        scwin.init_recvParam();
        scwin.init_rowCopy();
        await scwin.init_pageBody();
    } catch (e) {
        await $c.exception.handleError(e, { context: 'jlddst10200.onpageload' });
    }
};

/**
 * @method
 * @name init_rowCopy
 * @description dataList 단건 표시 복사 — 진입점에서 1회. 데이터 재적재 시 ev:ondataload 가 다시 부른다.
 * @returns {void}
 * @hidden N
 */
scwin.init_rowCopy = function () {
    const rows = [{ childId: "ipt_paxreq", fn: function () { return String(String((dma_pageContext.get("paxreq") ?? ""))); } },
        { childId: "ipt_outsvcno", fn: function () { return String(String((dma_pageContext.get("outsvcno") ?? ""))); } }];
    rows.forEach(function (it) {
        const c = $c.util.getComponent(it.childId);
        if (!c || typeof c.setValue !== "function") { return; }  // as-is 가 서버 렌더로 그리던 반복 행 — 산출에 없는 칸은 건너뛴다
        let v;
        try { v = it.fn(); } catch (e) { $c.exception.handleError(e, { notify: "none", context: "rowCopy:" + it.childId }); return; }
        if (v !== undefined && v !== null && String(v).trim() !== "") { c.setValue(String(v)); }
    });
};

/**
 * @method
 * @name init_pageBody
 * @description 초기화 — page Body
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.init_pageBody = async function () {
    try {
        if ($c.util.getComponent('ipt_paxreq').getValue() === "y") {
            (console.error('[sdd] 이 화면 문서에 #titleValue 가 없다 — append() 무동작(as-is 는 공용 템플릿·소거된 요소를 잡았다)'), $("#titleValue")).append("(PAXNET)");
        } else {
            if ($c.util.getComponent('ipt_outsvcno').getValue() === "02") {
                (console.error('[sdd] 이 화면 문서에 #titleValue 가 없다 — append() 무동작(as-is 는 공용 템플릿·소거된 요소를 잡았다)'), $("#titleValue")).append("(헤럴드미디어)");
            }
        }
        $c.util.getComponent("tabContents").setStyle("display", "none");
        /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
        if (($c.util.getComponent('AKCKwd').getValue() == null ? '' : String($c.util.getComponent('AKCKwd').getValue())) !== '') {
            await scwin.fnSearchCorpBasicInfo('');
        } else {
            await scwin.fnInitComNmSetting();
        }

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst10200.onpageload' }); }
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name searchForm_onsubmit
 * @description searchForm onsubmit 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.searchForm_onsubmit = function(e){
    try {
        return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst10200.searchForm_onsubmit' }); }
};

/**
 * @method
 * @name btn_fnFindCorpName2_onclick
 * @description btn_fnFindCorpName2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.btn_fnFindCorpName2_onclick = function(e){
    try {
        /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnFindCorpName2( " ') */ return false;

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jlddst10200.btn_fnFindCorpName2_onclick' }); }
};

/**
 * @method
 * @name btn_fnSearchCorpBasicInfo_onclick
 * @description btn_fnSearchCorpBasicInfo 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSearchCorpBasicInfo_onclick = async function(e){
    try {
        await scwin.fnSearchCorpBasicInfo(''); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst10200.btn_fnSearchCorpBasicInfo_onclick' }); }
};

/**
 * @method
 * @name btn_fnSearchCorpBasicInfo_2_onclick
 * @description btn_fnSearchCorpBasicInfo_2 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_fnSearchCorpBasicInfo_2_onclick = async function(e){
    try {
        await scwin.fnSearchCorpBasicInfo('print'); return false;

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jlddst10200.btn_fnSearchCorpBasicInfo_2_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fnSearch
 * @description fn Search 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch = async function () {
    const sbmOptions = {
        id: "tx_fnSearch",
        method: "post",
        action: "/corpdetail/changeinfo.do",
        ref: "dma_fnSearchReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

/**
 * @method
 * @name tx_fnSearch_ajaxsubmit
 * @description fn Search ajaxsubmit 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fnSearch_ajaxsubmit = async function () {
    const sbmOptions = {
        id: "tx_fnSearch_ajaxsubmit",
        method: "post",
        action: "/corpdetail/changeinfo.do",
        ref: "dma_fnSearchAjaxsubmitReq",
        isProcessMsg: false
    };
    const res = await $c.sbm.executeDynamic(sbmOptions);
    if (res && res.skipped) { return res; }  // 중복 제출 skip
    if (!(res && res.responseJSON && res.responseJSON.success === true)) {
        const m = (res && res.responseJSON && res.responseJSON.message) || $c.sbm.getStatusMessage(res) || ('서버 응답 오류 (' + $c.sbm.getResultCode(res) + ')');
        await $c.win.alert(m);
    }
    return res;
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name keyEvent
 * @description key Event 처리
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.keyEvent = async function (e) {
    if ($c.util.getKeyCode(typeof e !== 'undefined' && e ? e : (typeof event !== 'undefined' ? event : undefined)) === 13 || (typeof e !== 'undefined' && e === 13)) {
        if ($c.util.getKeyCode(event) === 13) {
            if (fnAKCKwdSearchCodeType(($c.util.getComponent('AKCKwd')))) {
                await scwin.fnSearchCorpBasicInfo('');
            }
        }
    }
};

/**
 * @method
 * @name fnInitComNmSetting
 * @description fn Init Com Nm Setting 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnInitComNmSetting = async function () {
    const comnm = scwin.fnGetRecentCompanyFromCookie();
    if (comnm != null && comnm !== "") {
        $c.util.getComponent('AKCKwd').setValue(comnm);
        await scwin.fnSearchCorpBasicInfo('');
    }
};

/**
 * @method
 * @name fnGetRecentCompanyFromCookie
 * @description fn Get Recent Company From Cookie 처리
 * @returns {void}
 * @hidden N
 */
scwin.fnGetRecentCompanyFromCookie = function () {
    const cookies = scwin.fnGetCookie('krxComp');
    const item = null;
    let userCompaniesArray = null;
    let tmpstr = null;
    if (cookies != null) {
        userCompaniesArray = cookies.split("/");
    }
    const issues = "";
    tmpstr = "";
    if (userCompaniesArray != null && userCompaniesArray !== "") {
        tmpstr = userCompaniesArray[0].split(",");
    }
    return tmpstr[2];
};

/**
 * @method
 * @name fnSearchCorpBasicInfo
 * @description fn Search Corp Basic Info 처리
 * @param {*} ipt_mode ipt_mode
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpBasicInfo = async function (ipt_mode) {
    let cd_or_nm = $c.util.getComponent('AKCKwd').getValue(); if (cd_or_nm == null) { cd_or_nm = ''; }
    if (cd_or_nm == null || cd_or_nm === "") {
        await $c.win.alert("회사명 또는 종목코드를 입력해 주세요.");
        return;
    }
    $c.util.getComponent("dma_fnSearchReq").set("isurCd", "");
    $c.util.getComponent("dma_fnSearchReq").set("kisComCd", "");
    $c.util.getComponent("dma_fnSearchReq").set("repIsuCd", "");
    if (ipt_mode === 'print') {
        $c.util.getComponent("dma_fnSearchReq").set("mode", "print");
    } else {
        $c.util.getComponent("dma_fnSearchReq").set("mode", "");
    }
    $c.util.getComponent("dma_fnSearchReq").set("searchCorpName", cd_or_nm);
    /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnAKCKwdSearchCorpName( " ') */
};

/**
 * @method
 * @name fnSearchCorpNameAllCallBack
 * @description fn Search Corp Name All Call Back 처리
 * @param {*} items items
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearchCorpNameAllCallBack = async function (items) {
    if (items.length === 1) {
        await scwin.fnSetCorpBasicInfo(items[0]);
    } else {
        if (items.length > 1) {
            /* TODO Stage2: [sdd] 미실현(재설계 분류 #128): fnFindCorpName2( " ') */
        } else {
            await scwin.fnSetCorpBasicInfo(null);
        }
    }
};

/**
 * @method
 * @name fnSetCorpBasicInfo
 * @description fn Set Corp Basic Info 처리
 * @param {*} items items
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSetCorpBasicInfo = async function (items) {
    if (items == null) {
        const val = ($c.util.getComponent("dma_fnSearchReq").get("searchCodeType") || '');
        if (val === "number") {
            await $c.win.alert("조회한 종목코드가 존재하지 않습니다.");
        } else {
            await $c.win.alert("조회한 회사명이 존재하지 않습니다.");
        }
        $c.util.getComponent("dma_fnSearchReq").set("isurCd", "");
        $c.util.getComponent("dma_fnSearchReq").set("kisComCd", "");
        $c.util.getComponent("dma_fnSearchReq").set("repIsuCd", "");
        $c.util.getComponent('AKCKwd').setValue("");
        $c.util.getComponent("AKCKwd").focus();  // 포커스 대상: 앞 문장이 가리키는 입력칸(as-is <폼>.<필드>.focus())
    } else {
        const isurcd = items.isurcd;
        const kiscomcd = items.kiscomcd;
        const repisucd = items.repisucd;
        const comabbr = items.comabbrv;
        $c.util.getComponent("dma_fnSearchReq").set("isurCd", isurcd);
        $c.util.getComponent("dma_fnSearchReq").set("kisComCd", kiscomcd);
        $c.util.getComponent("dma_fnSearchReq").set("repIsuCd", repisucd);
        $c.util.getComponent('AKCKwd').setValue(comabbr);
        await scwin.fnSearch();
    }
};

/**
 * @method
 * @name fnSearch
 * @description fn Search 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.fnSearch = async function () {
    let comAbbrv = $c.util.getComponent('AKCKwd').getValue(); if (comAbbrv == null) { comAbbrv = ''; }
    if (comAbbrv == null || comAbbrv === "") {
        await $c.win.alert("회사명을 입력해 주세요.");
        return;
    }
    /* TODO Stage2: [sdd] 미실현 동작: set_visible (대상 미해석) — 전환 미완 */ /* unresolved-target intent:set_visible — {target}.setStyle({args}) */
    $c.util.getComponent("tabContents").setStyle("display", "");
    $c.util.getComponent("dma_fnSearchReq").set("companyNM", encodeURI(comAbbrv));
    if (($c.util.getComponent("dma_fnSearchReq").get("mode") || '') === 'print') {
        $("#searchForm").attr('onsubmit', '');
        $("#searchForm").attr('target', 'print');
        scwin.gShowWindow("", "print", "850", "700", "");
        $c.util.getComponent("dma_fnSearchReq").set("method", "searchCorpChgInfo");
        await scwin.tx_fnSearch();
        $("#searchForm").attr('onsubmit', 'return false;');
        $("#searchForm").attr('target', '');
        $("#searchForm").attr('action', '');
    } else {
        $("#searchForm").attr('onsubmit', 'return false;');
        $("#searchForm").attr('target', '');
        $("#searchForm").attr('action', '');
        $c.util.getComponent("dma_fnSearchReq").set("method", "searchCorpChgInfo");
        await scwin.tx_fnSearch_ajaxsubmit();
    }
};

/**
 * @method
 * @name fnSearchCallBack
 * @description fn Search Call Back 처리
 * @param {*} data 데이터
 * @returns {void}
 * @hidden N
 */
scwin.fnSearchCallBack = function (data) {
    $("#mainContents").empty().append(data);
};

/**
 * @method
 * @name setCorpInfo2
 * @description set Corp Info2 처리
 * @param {String} ipt_isurCd ipt_isurCd
 * @param {String} ipt_kisComCd ipt_kisComCd
 * @param {String} ipt_repIsuCd ipt_repIsuCd
 * @param {String} repIsuKorNm repIsuKorNm
 * @param {String} repIsuSrtCd repIsuSrtCd
 * @param {String} comNm comNm
 * @param {*} comAbbrv comAbbrv
 * @param {*} isurSymbl isurSymbl
 * @param {*} fssUnqNo fssUnqNo
 * @param {*} marketType marketType
 * @returns {void}
 * @hidden N
 */
scwin.setCorpInfo2 = function (ipt_isurCd, ipt_kisComCd, ipt_repIsuCd, repIsuKorNm, repIsuSrtCd, comNm, comAbbrv, isurSymbl, fssUnqNo, marketType) {
    $c.util.getComponent("dma_fnSearchReq").set("isurCd", ipt_isurCd);
    $c.util.getComponent("dma_fnSearchReq").set("kisComCd", ipt_kisComCd);
    $c.util.getComponent("dma_fnSearchReq").set("repIsuCd", ipt_repIsuCd);
    $c.util.getComponent('AKCKwd').setValue(comAbbrv);
};

/**
 * @method
 * @name fnGetCookie
 * @description fn Get Cookie 처리
 * @param {*} keyname keyname
 * @returns {void}
 * @hidden N
 */
scwin.fnGetCookie = function (keyname) { const v = $c.util.getSessionStorage(keyname); return (v === undefined || v === null) ? '' : v; };

/**
 * @method
 * @name gShowWindow
 * @description g Show Window 처리
 * @param {*} strPageURL strPageURL
 * @param {*} strWindowName strWindowName
 * @param {*} lngWidth lngWidth
 * @param {*} lngHeight lngHeight
 * @param {*} strOptions strOptions
 * @returns {void}
 * @hidden N
 */
scwin.gShowWindow = function (strPageURL, strWindowName, lngWidth, lngHeight, strOptions) {
    let lngTop, lngLeft;
    if (strOptions === "") {
        strOptions = "toolbar=no, location=no, menubar=no, scrollbars=yes, status=yes, resizable=no";
    }
    lngTop = (screen.height - lngHeight) / 2;
    lngLeft = (screen.width - lngWidth) / 2;
    strOptions = strOptions + ", width=" + lngWidth + ", height=" + lngHeight + ", top=" + lngTop + ", left=" + lngLeft;
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — "
    const newWin = $c.win.openPopup((function (__u) { const __s = String(__u == null ? "" : __u); if (!/\.xml(\?|#|$)/.test(__s)) { throw { bizMessage: "이 화면의 이동 목적지를 아직 정하지 못했습니다(전환 미완) — " + __s, unresolved: "nav:" + __s }; } return __u; })(strPageURL), { id: strWindowName }, {});
};
